window.CARDS=[{"id":"k001","d":"마음가짐","f":"부자를 재는 세 가지 잣대","b":["① 순자산 = 자산 − 부채","② 현금흐름 = 들어오는 돈 − 나가는 돈","③ 선택권 = 돈 때문에 원치 않는 선택을 하지 않아도 되는 자유","겉으로 보이는 소비는 잣대가 아님"]},{"id":"k002","d":"마음가짐","f":"72의 법칙","b":["72 ÷ 연 수익률 = 두 배가 되는 햇수","3% → 24년, 6% → 12년, 8% → 9년","빚에도 적용: 연 18% 카드론 → 4년"]},{"id":"k003","d":"마음가짐","f":"부자가 되는 공식","b":["(번 돈 − 쓴 돈) × 시간 × 수익률","내가 조절할 수 있는 것: 번 돈, 쓴 돈, 시간","수익률은 마지막에 신경 써도 됨"]},{"id":"k004","d":"마음가짐","f":"손실과 회복 수익률","b":["−10% → +11.1%","−20% → +25%","−30% → +42.9%","−50% → +100%","−80% → +400%"]},{"id":"k005","d":"마음가짐","f":"2026년 11월 경제 숫자","b":["기준금리 3.00% (10월 22일 동결)","9월 소비자물가 2.9%","11월 6일 코스피 −6.02% (5,059.69)"]},{"id":"k006","d":"돈 관리","f":"지출 세 가지","b":["고정 필수비: 월세·통신비·보험료·대출이자","변동 필수비: 식비·교통비·생활용품","선택 지출: 외식·여행·쇼핑 → 미리 정한 만큼만"]},{"id":"k007","d":"돈 관리","f":"고정비 점검 3질문","b":["① 매달 자동으로 나가는가?","② 1년·10년 합치면 얼마인가?","③ 없애면 삶이 정말 나빠지는가? → \"아니오\"면 줄이기"]},{"id":"k008","d":"돈 관리","f":"3대 고정비","b":["주거비 (소득의 30% 이하)","자동차 (월 총비용으로 계산)","보험료 (중복·불필요 특약 정리)"]},{"id":"k009","d":"돈 관리","f":"월급이 오르면","b":["① 생활 수준은 천천히","② 인상분 절반 이상 자동이체로 분리","③ 세제 혜택 계좌(ISA·연금저축·IRP) 채우기","④ 일부는 나의 소득 능력에 재투자"]},{"id":"k010","d":"돈 관리","f":"통장 쪼개기","b":["월급 통장 → 바로 나누어 보냄","생활비 통장 + 체크카드","비상금 통장 (파킹통장·CMA)","투자 통장 (ISA·연금저축)"]},{"id":"k011","d":"돈 관리","f":"비상금의 크기","b":["기본: 월 필수 생활비 3~6개월","소득 불안정·외벌이: 6~12개월","은퇴 가까운 50대 이후: 1~2년치 안전 자산"]},{"id":"k012","d":"돈 관리","f":"비상금의 3대 역할","b":["① 고금리 빚을 쓰지 않게 막는다","② 주식·부동산을 나쁜 시기에 팔지 않게 지킨다","③ 실직·질병 때 서두르지 않을 시간을 준다"]},{"id":"k013","d":"돈 관리","f":"예금자보호 한도","b":["2025년 9월 1일부터 1인당 금융회사별 1억 원","증권사 CMA 일부·펀드·주식은 보호 대상 아님"]},{"id":"k014","d":"돈 관리","f":"청년미래적금 (발표 조건)","b":["만 19~34세, 총급여 7,500만 원 이하 등","월 최대 50만 원, 3년","정부 기여금 6% (일반형) / 12% (우대형)"]},{"id":"k015","d":"빚·투자","f":"좋은 빚 vs 나쁜 빚","b":["좋은 빚: 상환 재원이 현금흐름, 금리 2%p 상승도 감당","나쁜 빚: 소비에 쓰고 아무것도 안 남음 (여행·명품·신차 할부·현금서비스)"]},{"id":"k016","d":"빚·투자","f":"빚 갚는 순서","b":["눈사태 방식: 이자율 높은 빚부터 (수학적으로 유리)","눈덩이 방식: 금액 작은 빚부터 (성취감)","카드론·현금서비스·리볼빙을 가장 먼저"]},{"id":"k017","d":"빚·투자","f":"DSR","b":["1년 모든 대출 원리금 ÷ 연소득","은행 원칙 40% = 최대한도, 적정선 아님","권장: 세후 소득의 25~30% 이내"]},{"id":"k018","d":"빚·투자","f":"고금리 시대 빚 점검 3가지","b":["① 금리 2%p 오르면 월 상환액은?","② 대출 만기가 은퇴보다 늦지 않은가?","③ 상환 재원이 월급인가, 자산 가격 상승인가?"]},{"id":"k019","d":"빚·투자","f":"레버리지를 쓸 수 있는 조건","b":["① 상환 재원이 현금흐름","② 30~50% 떨어져도 강제로 안 팔림","③ 금리가 올라도 이자를 낼 수 있음","④ 한 자산에 몰지 않음"]},{"id":"k020","d":"빚·투자","f":"투자 초보의 기본 순서","b":["① 비상금 먼저","② 세제 혜택 계좌 열기","③ 넓게 분산된 지수 ETF","④ 매달 같은 날 적립식","⑤ 개별 종목은 공부한 만큼만 작게"]},{"id":"k021","d":"빚·투자","f":"자산배분과 리밸런싱","b":["참고 규칙: 주식 비중 = 100 − 나이","돈 쓸 시기가 가까우면 주식 비중 줄이기","1년에 한두 번 처음 비율로 되돌리기"]},{"id":"k022","d":"빚·투자","f":"폭락장에서 하지 않는 행동","b":["겁에 질려 전부 매도","바닥 맞히려 한 번에 몰빵","빚 내서 물타기","비상금까지 투자","뉴스 따라 잦은 매매"]},{"id":"k023","d":"빚·투자","f":"폭락장의 승자","b":["가장 잘 맞힌 사람이 아니라 가장 오래 버틴 사람","버틸 힘: 비상금 · 빚 없는 투자 · 분산 · 미리 정한 규칙"]},{"id":"k024","d":"세금","f":"금융소득 세금","b":["이자·배당: 15.4% 원천징수","연 2,000만 원 넘으면 금융소득종합과세 (최고 49.5%)"]},{"id":"k025","d":"세금","f":"ISA (일반형)","b":["의무 가입 3년","비과세 200만 원 (서민형 400만 원), 초과 9.9%","연 2,000만 원, 총 1억 원 (이월 가능)","만기 60일 안 연금 이전 → 10% (최대 300만 원) 추가 공제"]},{"id":"k026","d":"세금","f":"연금저축 + IRP 세액공제","b":["한도: 연금저축 600만 원, 합산 900만 원","총급여 5,500만 원 이하 16.5% → 148만 5,000원","초과 13.2% → 118만 8,000원"]},{"id":"k027","d":"세금","f":"연금 받을 때 세금","b":["70세 미만 5.5%, 70~79세 4.4%, 80세 이상 3.3%","연금 외 수령: 기타소득세 16.5%"]},{"id":"k028","d":"세금","f":"고배당 기업 배당 분리과세","b":["2026~2028년 지급분","14% · 20% · 25% · 30%","해외 주식 배당·ETF 분배금 제외"]},{"id":"k029","d":"집·소득","f":"취득세 (1주택)","b":["6억 원 이하 1%","6억~9억 원 1~3%","9억 원 초과 3%","규제지역 2주택 8%, 3주택 이상 12%"]},{"id":"k030","d":"집·소득","f":"집의 진짜 가격","b":["집값 + 취득 부대비용 (4~5%)","+ 입주 비용 + 보유 기간 이자·세금·관리비","+ 자기 자본의 기회비용 + 팔 때 비용"]},{"id":"k031","d":"집·소득","f":"규제지역 주담대 한도","b":["15억 원 이하: 6억 원","15억~25억 원: 4억 원","25억 원 초과: 2억 원","LTV 40% (생애 최초 70%)"]},{"id":"k032","d":"집·소득","f":"집 살 때 3가지 계산","b":["① 금리 2%p 올라도 월 상환액 감당?","② 실거래가 기준으로 적정?","③ 사고도 비상금 (최소 6개월)과 노후 저축 유지?"]},{"id":"k033","d":"집·소득","f":"최저임금","b":["2026년 시간당 10,320원 (월 약 215만 7,000원)","2027년 시간당 10,700원 (월 약 223만 6,000원)"]},{"id":"k034","d":"집·소득","f":"좋은 부업 5가지 조건","b":["① 시작과 끝이 분명","② 반복할수록 빨라짐","③ 본업과 충돌 없음","④ 초기 비용이 작음","⑤ 단골·반복 고객"]},{"id":"k035","d":"집·소득","f":"반복 수익의 3단계","b":["첫 고객 = 증거","두 번째 고객 = 복제 가능성","세 번째부터 = 시스템 (체크리스트·템플릿)"]},{"id":"k036","d":"집·소득","f":"반복 결제가 생기는 이유","b":["소모된다 (휴지·포장재)","다시 더러워진다 (에어컨 필터·배수구)","생활이 반복된다 (반찬·산책)","+ 귀찮음"]},{"id":"k037","d":"집·소득","f":"소자본 창업 3대 원칙","b":["① 큰 매장·장비 먼저 계약 안 함","② 좁은 지역에 고객 모으기 (이동 시간 최소화)","③ 두 번째 매출이 어디서 오는지 설계"]},{"id":"k038","d":"집·소득","f":"고령화 사업 성공 조건","b":["① 고객 밀도","② 실제 지불자 파악 (노부모·자녀·지자체)","③ 반복 수요","④ 신뢰 장치 (보험·자격·기록)","⑤ 일할 사람 확보"]},{"id":"k039","d":"노후·지키기","f":"노후 현금흐름의 층","b":["1층 국민연금","2층 퇴직연금 (DB·DC·IRP)","3층 개인연금","4층 예금·채권·배당주","5층 주택연금","6층 작은 사업·지식 자산"]},{"id":"k040","d":"노후·지키기","f":"국민연금 받는 시기","b":["1969년생 이후 만 65세","앞당기면 1년에 6% 감액 (최대 5년)","늦추면 1년에 7.2% 증액 (최대 5년)"]},{"id":"k041","d":"노후·지키기","f":"2026년 국민연금 개혁","b":["보험료율 9.5% → 매년 0.5%p → 2033년 13%","소득대체율 43%","직장인 본인 부담 4.75%","출산 크레딧 첫째부터, 군복무 최대 12개월"]},{"id":"k042","d":"노후·지키기","f":"노후 필요 자산 계산","b":["부족분 = 생활비 − 국민연금 − 퇴직연금","필요 자산 = 연 부족분 ÷ 인출률 (4% 또는 보수적으로 3~3.5%)"]},{"id":"k043","d":"노후·지키기","f":"주택연금","b":["부부 중 한 명 만 55세 이상","공시가격 12억 원 이하","평생 거주 + 종신 지급","부족해도 상속인에게 청구 안 함"]},{"id":"k044","d":"노후·지키기","f":"집보다 먼저 사는 7가지 자산","b":["① 비상금 (방패) ② 소득 능력 (엔진)","③ 연금 (기둥) ④ 분산 주식 (성장)","⑤ 채권 (균형) ⑥ 작은 사업 (추가 현금흐름)","⑦ 기회 자금"]},{"id":"k045","d":"노후·지키기","f":"꼭 필요한 보험","b":["실손의료보험 (중복 가입 낭비)","정기 사망보험 (부양가족 있으면)","배상책임보험 (저렴한 특약)","저축성·변액: 해지환급금 표 확인"]},{"id":"k046","d":"노후·지키기","f":"사기의 3대 신호","b":["급하게","비밀로","너무 좋은 조건 (원금 보장 + 고수익)","→ 멈추고, 끊고, 직접 확인"]},{"id":"k047","d":"노후·지키기","f":"사기 당했을 때","b":["즉시 112나 금융회사에 지급 정지 요청","금융감독원 1332 상담","숨기지 말고 바로 알리기"]},{"id":"k048","d":"노후·지키기","f":"나이대별 한 줄 요약","b":["20대 습관","30대 구조","40대 속도","50대 방어","60대 흐름"]},{"id":"k049","d":"노후·지키기","f":"증여세 공제 (10년)","b":["배우자 6억 원","성인 자녀 5,000만 원","미성년 자녀 2,000만 원","혼인·출산 시 1억 원 추가"]}];
